import * as T from '../vendor/three.module.js';
// Fixed pools: particle explosions do not allocate new scene objects per shot.
export function createEffects(scene){
 const capacity=360,particles=Array.from({length:capacity},()=>({life:0})),positions=new Float32Array(capacity*3),colors=new Float32Array(capacity*3),sizes=new Float32Array(capacity),alphas=new Float32Array(capacity);let cursor=0,shake=0;
 const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(positions,3));geometry.setAttribute('color',new T.BufferAttribute(colors,3));geometry.setAttribute('size',new T.BufferAttribute(sizes,1));geometry.setAttribute('alpha',new T.BufferAttribute(alphas,1));
 const material=new T.ShaderMaterial({transparent:true,depthWrite:false,vertexColors:true,vertexShader:'attribute float size;attribute float alpha;varying vec3 vColor;varying float vAlpha;void main(){vColor=color;vAlpha=alpha;vec4 p=modelViewMatrix*vec4(position,1.);gl_Position=projectionMatrix*p;gl_PointSize=clamp(size*300./max(1.,-p.z),1.,90.);}',fragmentShader:'varying vec3 vColor;varying float vAlpha;void main(){float r=length(gl_PointCoord-.5)*2.;if(r>1.)discard;gl_FragColor=vec4(vColor,vAlpha*(1.-smoothstep(.1,1.,r)));}'});
 const points=new T.Points(geometry,material);points.frustumCulled=false;scene.add(points);const flash=new T.PointLight('#ffac55',0,35,2);scene.add(flash);let lightLife=0;
 const debris=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color:'#45494d',roughness:.94}),100),pieces=Array.from({length:100},()=>({life:0}));debris.frustumCulled=false;debris.castShadow=true;scene.add(debris);const dummy=new T.Object3D();for(let i=0;i<100;i++){dummy.scale.setScalar(0);dummy.updateMatrix();debris.setMatrixAt(i,dummy.matrix);}let debrisCursor=0;
 function particle(p,color,size,life,vx,vy,vz,gravity=0){const i=cursor++%capacity;particles[i]={x:p.x,y:p.y,z:p.z,vx,vy,vz,life,total:life,gravity,size};colors.set(color,i*3);}
 function burst(p,explosion=false){const count=explosion?80:24;for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,v=(explosion?12:5)*Math.random(),smoke=explosion&&i>40;particle(p,smoke?[.22,.24,.27]:[1,.42+Math.random()*.45,.09],smoke?3+Math.random()*3:.15+Math.random()*.8,smoke?2.7: .35+Math.random()*.7,Math.cos(a)*v,(smoke?4:7)*Math.random(),Math.sin(a)*v,smoke?-1:10);}
 if(explosion){flash.position.set(p.x,p.y+2,p.z);lightLife=.35;for(let i=0;i<18;i++){const a=Math.random()*Math.PI*2;pieces[debrisCursor++%100]={x:p.x,y:p.y,z:p.z,vx:Math.cos(a)*(3+Math.random()*9),vy:5+Math.random()*12,vz:Math.sin(a)*(3+Math.random()*9),life:3,size:.15+Math.random()*.6,spin:Math.random()*5};}}}
 return {get shake(){return shake;},impact(p,intensity){shake=Math.max(shake,Math.min(1,intensity/8+.15));burst(p);},explode(p){burst(p,true);},trail(p){particle(p,[.8,.83,.85],.36,.55,0,.5,0);},update(dt){shake*=Math.exp(-7*dt);lightLife=Math.max(0,lightLife-dt);flash.intensity=lightLife*55;for(let i=0;i<capacity;i++){const p=particles[i];if(p.life>0){p.life-=dt;p.vy-=p.gravity*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;positions.set([p.x,p.y,p.z],i*3);sizes[i]=p.size*(1+(1-p.life/p.total)*1.5);alphas[i]=Math.max(0,p.life/p.total);}else alphas[i]=0;}for(const name of ['position','color','size','alpha'])geometry.attributes[name].needsUpdate=true;for(let i=0;i<100;i++){const p=pieces[i];if(p.life>0){p.life-=dt;p.vy-=20*dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(p.life*p.spin,p.life*2,0);dummy.scale.setScalar(Math.max(0,p.size*Math.min(1,p.life)));}else dummy.scale.setScalar(0);dummy.updateMatrix();debris.setMatrixAt(i,dummy.matrix);}debris.instanceMatrix.needsUpdate=true;}};
}
